import React, { useState } from 'react';
import './CodeViewer.css';

const LANGUAGES = [
  { id: 'javascript', label: 'JavaScript', icon: '⚡' },
  { id: 'python', label: 'Python', icon: '🐍' },
  { id: 'java', label: 'Java', icon: '☕' },
  { id: 'cpp', label: 'C++', icon: '⚙️' },
  { id: 'c', label: 'C', icon: '💻' },
  { id: 'csharp', label: 'C#', icon: '#' },
  { id: 'go', label: 'Go', icon: '🐹' },
  { id: 'rust', label: 'Rust', icon: '🦀' },
];

export default function CodeViewer({ codeSnippets, algoLabel }) {
  const [selectedLang, setSelectedLang] = useState('javascript');
  const [copied, setCopied] = useState(false);

  const code = codeSnippets[selectedLang] || '// Code not available';

  const handleCopy = () => {
    navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleDownload = () => {
    const langExtensions = {
      python: '.py',
      java: '.java',
      cpp: '.cpp',
      c: '.c',
      csharp: '.cs',
      go: '.go',
      rust: '.rs',
      javascript: '.js',
    };
    
    const ext = langExtensions[selectedLang] || '.txt';
    const filename = `${algoLabel.toLowerCase().replace(/\s+/g, '_')}${ext}`;
    const element = document.createElement('a');
    element.setAttribute('href', 'data:text/plain;charset=utf-8,' + encodeURIComponent(code));
    element.setAttribute('download', filename);
    element.style.display = 'none';
    document.body.appendChild(element);
    element.click();
    document.body.removeChild(element);
  };

  return (
    <div className="code-viewer">
      <div className="code-viewer-header">
        <h3>Code Implementation</h3>
        <div className="code-viewer-actions">
          <button className="code-action-btn" onClick={handleCopy} title="Copy code">
            {copied ? '✓ Copied!' : '📋 Copy'}
          </button>
          <button className="code-action-btn" onClick={handleDownload} title="Download code">
            ⬇️ Download
          </button>
        </div>
      </div>

      <div className="language-tabs">
        {LANGUAGES.map(lang => (
          <button
            key={lang.id}
            className={`lang-tab ${selectedLang === lang.id ? 'lang-tab-active' : ''}`}
            onClick={() => setSelectedLang(lang.id)}
          >
            <span className="lang-icon">{lang.icon}</span>
            {lang.label}
          </button>
        ))}
      </div>

      <pre className="code-block">
        <code>{code}</code>
      </pre>
    </div>
  );
}
